#!/usr/bin/env bash
# Lab .env format: unquoted, single-line KEY=value, as generated by init-env.sh.
set -Eeuo pipefail
APP_ROOT="${APP_ROOT:-$(cd "$(dirname "$0")/.." && pwd)}"
cd "$APP_ROOT"
[[ "$(kubectl config current-context)" == kind-urlshortener ]] || {
  echo 'Select the kind-urlshortener context before creating lab secrets' >&2
  exit 1
}
keys=(DB_NAME DB_USERNAME DB_PASSWORD JWT_SECRET SUPER_ADMIN_EMAIL SUPER_ADMIN_PASSWORD
      ADMIN_EMAIL ADMIN_PASSWORD VNPAY_TMN_CODE VNPAY_HASH_SECRET VNPAY_RETURN_URL)
declare -A values=()
while IFS= read -r line || [[ -n "$line" ]]; do
  line="${line%$'\r'}"
  [[ -z "$line" || "$line" == \#* ]] && continue
  [[ "$line" == *=* ]] || { echo 'Invalid lab .env line' >&2; exit 1; }
  values["${line%%=*}"]="${line#*=}"
done < .env
umask 077
secret_file=$(mktemp)
trap 'rm -f "$secret_file"' EXIT
for key in "${keys[@]}"; do
  [[ -n "${values[$key]:-}" ]] || { echo "Missing $key in .env" >&2; exit 1; }
  value="${values[$key]}"
  if [[ "$key" == VNPAY_RETURN_URL ]]; then
    value='http://localhost:18080/api/v1/billing/vnpay-return'
  fi
  printf '%s=%s\n' "$key" "$value" >> "$secret_file"
done
kubectl -n urlshortener create secret generic app-secrets --from-env-file="$secret_file" \
  --dry-run=client -o yaml | kubectl apply -f -
